installer-gui-script.script:
function domovoiCheck() {
  // Apple Silicon (hostArchitectures above), macOS 26 or later, 16 GB.
  if (system.compareVersions(system.version.ProductVersion, '26.0') < 0) {
    my.result.type = 'Fatal';
    my.result.title = 'Domovoi needs macOS 26 or later';
    my.result.message = 'This Mac runs macOS ' + system.version.ProductVersion + '. Update it in System Settings > General > Software Update, then open this package again.';
    return false;
  }
  var mem = system.sysctl('hw.memsize');
  if (mem < 16 * 1024 * 1024 * 1024) {
    my.result.type = 'Fatal';
    my.result.title = 'Domovoi needs 16 GB of memory';
    my.result.message = 'This Mac has ' + Math.round(mem / (1024 * 1024 * 1024)) + ' GB.';
    return false;
  }
  return true;
}
